const upsertInstanceService = `-- name: UpsertInstanceService :one
INSERT INTO instance_services (kind, status, message, endpoint)
VALUES ($1, $2, $3, $4)
ON CONFLICT (kind) DO UPDATE
SET status = EXCLUDED.status, message = EXCLUDED.message, endpoint = EXCLUDED.endpoint, updated_at = now()
RETURNING kind, status, message, endpoint, options, secrets_enc, updated_at
`

type UpsertInstanceServiceParams struct {
	Kind     string `json:"kind"`
	Status   string `json:"status"`
	Message  string `json:"message"`
	Endpoint string `json:"endpoint"`
}

// The control plane's view of one kind: status, message and endpoint. Options and
// secrets are left alone when the row exists.
func (q *Queries) UpsertInstanceService(ctx context.Context, arg UpsertInstanceServiceParams) (InstanceService, error) {
	row := q.db.QueryRow(ctx, upsertInstanceService,
		arg.Kind,
		arg.Status,
		arg.Message,
		arg.Endpoint,
	)
	var i InstanceService
	err := row.Scan(
		&i.Kind,
		&i.Status,
		&i.Message,
		&i.Endpoint,
		&i.Options,
		&i.SecretsEnc,
		&i.UpdatedAt,
	)
	return i, err
}
